import re

def clean_num(s):
    if s is None: return None
    s = str(s).strip()
    if not s or s == '—' or s == '-': return None
    s = s.replace('$', '').replace('£', '').replace(',', '').strip()
    if s.startswith('(') and s.endswith(')'):
        s = '-' + s[1:-1]
    try:
        # Handle percentage if it's the only thing in the string
        if s.endswith('%'):
            return float(s[:-1]) / 100.0
        return float(s)
    except ValueError:
        return None

def extract_year(s):
    if s is None: return None
    match = re.search(r'\b(20\d{2})\b', str(s))
    return float(match.group(1)) if match else None

def get_table_node(doc, scope):
    scope_node = node_by_title(doc, scope)
    if not scope_node: return None
    for child in children(doc, scope_node):
        if child['kind'] == 'table':
            return child
    return None

def get_time_mapping(table_node):
    """Returns ('cols' or 'rows', mapping_of_time_to_index)."""
    cols = table_node['columns']
    rows = table_node['table']['rows']

    # Check columns for years
    col_times = {}
    for i, col in enumerate(cols):
        t = extract_year(col)
        if t: col_times[t] = i

    # Check top rows for years (sometimes years are in the first few rows)
    for r_idx in range(min(3, len(rows))):
        for c_idx, cell in enumerate(rows[r_idx]):
            t = extract_year(cell)
            if t: col_times[t] = c_idx

    if col_times:
        return 'cols', col_times

    # Check rows' first column for years
    row_times = {}
    for r_idx, row in enumerate(rows):
        if not row: continue
        t = extract_year(row[0])
        if t: row_times[t] = r_idx

    if row_times:
        return 'rows', row_times

    return None, None

