    if not s or s in ('—', '-', 'n/a', 'None'): return None
    s = s.replace('$', '').replace('£', '').replace(',', '').strip()
    if s.startswith('(') and s.endswith(')'):
        s = '-' + s[1:-1]
    try:
        if s.endswith('%'):
            return float(s[:-1]) / 100.0
        return float(s)
    except ValueError:
        return None

def extract_year(s):
    if not s: return None
    s = str(s)
    match = re.search(r'20\d{2}', s)
    if match: return float(match.group(0))
    match = re.search(r'F(\d{2})', s)
    if match: return float("20" + match.group(1))
    return None

def get_metric_name(header, year):
    # Remove the year part to get the metric name
    year_str = str(int(year))
    # Also try the 'F19' style
    f_year = f"F{str(int(year))[-2:]}"

    s = header
