def is_metric(label):
    metrics = {
        'revenue', 'sales', 'ebitda', 'profit', 'income', 'assets', 'liabilities', 
        'depreciation', 'amortisation', 'amortization', 'impairment', 'expenses', 
        'cost of sales', 'earnings', 'capital additions', 'cash flow', 'equity'
    }
    l = label.lower()
    return any(m in l for m in metrics)

